model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  productId: ID
  productName: String
  price: Number
  quantity: Number
}

component ProductCard(product: Product, onAdd: Fn) {
  card pad=4 gap=2 {
    text product.name bold
    text `$${product.price.toFixed(2)}` small muted
    button "Agregar" primary -> onAdd(product)
  }
}

component CartItemRow(item: CartItem, onIncrease: Fn, onDecrease: Fn) {
  row gap=4 align=center {
    text item.productName
    text `$${item.price.toFixed(2)}` small muted
    row gap=2 align=center {
      button "-" small -> onDecrease(item.productId)
      text `${item.quantity}` bold
      button "+" small -> onIncrease(item.productId)
    }
    text `$${(item.price * item.quantity).toFixed(2)}` bold
  }
}

page Shop "/" {
  state products: Product[] = [
    { id: "1", name: "Laptop", price: 999.99 },
    { id: "2", name: "Mouse", price: 29.99 },
    { id: "3", name: "Teclado", price: 79.99 }
  ]

  state cart: CartItem[] = []

  computed total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0)

  fn addToCart(product: Product) {
    let existing = cart.find(item => item.productId == product.id)
    if existing {
      existing.quantity++
    } else {
      cart.push({
        productId: product.id,
        productName: product.name,
        price: product.price,
        quantity: 1
      })
    }
    cart = [...cart]
  }

  fn increaseQuantity(productId: ID) {
    let item = cart.find(item => item.productId == productId)
    if item {
      item.quantity++
      cart = [...cart]
    }
  }

  fn decreaseQuantity(productId: ID) {
    cart = cart
      .map(item => item.productId == productId ? { ...item, quantity: item.quantity - 1 } : item)
      .filter(item => item.quantity > 0)
  }

  row gap=8 pad=4 {
    column gap=4 {
      title "Productos"
      for p in products key p.id {
        ProductCard product=p onAdd=addToCart
      }
    }

    column gap=4 {
      title "Carrito"
      if cart.length == 0 {
        text "El carrito está vacío" muted
      } else {
        column gap=2 {
          for item in cart key item.productId {
            CartItemRow item=item onIncrease=increaseQuantity onDecrease=decreaseQuantity
          }
          divider
          row gap=2 justify=between {
            text "Total:" bold large
            text `$${total.toFixed(2)}` bold large primary
          }
        }
      }
    }
  }
}

model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
