}

page Shop "/" {
  state cart: CartItem[] = []

  fn products() {
    return [
      { id: "1", name: "Laptop", price: 999.99 },
      { id: "2", name: "Mouse", price: 29.99 },
      { id: "3", name: "Keyboard", price: 79.99 }
    ]
  }

  fn addToCart(product: Any) {
    let existing = cart.find(item => item.productId == product.id)
    if existing {
      existing.quantity++
    } else {
      cart.push({
        productId: product.id,
        name: product.name,
        price: product.price,
        quantity: 1
      })
    }
  }

  fn increaseQuantity(productId: ID) {
    let item = cart.find(item => item.productId == productId)
    if item {
      item.quantity++
    }
  }

  fn decreaseQuantity(productId: ID) {
    let item = cart.find(item => item.productId == productId)
    if item {
      item.quantity--
      if item.quantity == 0 {
        cart = cart.filter(x => x.productId != productId)
      }
    }
  }

  computed total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0)

  column gap=4 pad=4 {
    title "Shopping Cart"

    row gap=4 {
      column gap=2 {
        text "Products" bold large
        for product in products() key product.id {
          card gap=2 pad=2 {
            column gap=2 {
              text product.name bold
              text `$${product.price.toFixed(2)}` muted
              button "Add to Cart" primary -> addToCart(product)
            }
          }
        }
      }

      column gap=2 {
        text "Cart" bold large
        if cart.length == 0 {
          text "Your cart is empty" muted
        } else {
          card gap=2 pad=2 {
            column gap=2 {
              for item in cart key item.productId {
                CartItemRow item=item onIncrease=increaseQuantity onDecrease=decreaseQuantity
              }
              divider
              row gap=2 align=center justify="space-between" {
                text "Total:" bold
                text `$${total.toFixed(2)}` bold large primary
              }
            }
          }
        }
      }
    }
  }
}

