    if authorName.trim() == "" { return }
    try {
      await api.authors.create({ name: authorName.trim() })
      authorName = ""
      authors = await api.authors.list()
    } catch (e) {
      if e.details?.name {
        authorName = "Autor ya existe"
      }
    }
  }

