    let authorPosts = posts.filter(p => p.author.id == authorId)
    if authorPosts.length > 0 {
      alert("El autor tiene posts")
      return
    }
    try {
      await api.authors.remove(authorId)
      authors = await api.authors.list()
    } catch (e) {
      // error
    }
  }

  column gap=4 pad=4 {
    title "Blog"

    column gap=2 {
      title "Crear Autor" tag=h2
      row gap=2 {
