    column gap=2 {
      title "Autores" tag=h2
      if authors.length == 0 {
        text "Sin autores" muted
      } else {
        for author in authors key author.id {
          AuthorItem author=author onDelete=(id => deleteAuthor(id))
        }
      }
    }

    column gap=2 {
      title "Crear Post" tag=h2
      row gap=2 {
        input postTitle placeholder="Título"
        select selectedAuthorId options=(authors.map(a => ({ value: a.id, label: a.name })))
        button "Publicar" primary -> addPost()
      }
    }

    column gap=2 {
      title "Posts" tag=h2
      if posts.length == 0 {
        text "Sin posts" muted
      } else {
        for post in posts key post.id {
          PostItem post=post
        }
      }
    }
  }
}

