  name: String min=1
}

model Post {
  id: ID
  title: String min=1
  author: Author
}

api authors: Author
api posts: Post

page Home "/" {
  state authorName = ""
  state postTitle = ""
  state selectedAuthorId: String? = null
  data authors = api.authors.list()
  data posts = api.posts.list()

  fn addAuthor() {
    if authorName.trim() == "" { return }
    try {
      await api.authors.create({ name: authorName.trim() })
      authorName = ""
    } catch (e) {
      console.error(e.message)
    }
  }

  fn publishPost() {
    if postTitle.trim() == "" || !selectedAuthorId { return }
    try {
      await api.posts.create({ title: postTitle.trim(), author: selectedAuthorId })
      postTitle = ""
      selectedAuthorId = null
    } catch (e) {
      console.error(e.message)
    }
  }

  fn deleteAuthor(authorId: String) {
    let authorPosts = posts.filter(p => p.author.id == authorId)
    if authorPosts.length > 0 {
      alert("El autor tiene posts")
      return
    }
    try {
      await api.authors.remove(authorId)
    } catch (e) {
      console.error(e.message)
    }
  }

  column gap=4 pad=4 {
    title "Blog"

    card {
      title "Crear autor" tag=h2
      row gap=2 {
        input authorName placeholder="Autor"
        button "Crear autor" primary -> addAuthor()
      }
    }

    card {
      title "Publicar post" tag=h2
      column gap=2 {
        input postTitle placeholder="Título"
        select selectedAuthorId options=(authors.map(a => ({ value: a.id, label: a.name })))
        button "Publicar" primary -> publishPost()
      }
    }

    card {
      title "Autores" tag=h2
      if authors.length == 0 {
        text "Sin autores" muted
      } else {
        for author in authors key author.id {
          row gap=2 align=center {
            text author.name
            button "Borrar autor" danger small -> deleteAuthor(author.id)
          }
        }
      }
    }

    card {
      title "Posts" tag=h2
      if posts.length == 0 {
        text "Sin posts" muted
      } else {
        for post in posts key post.id {
          column gap=1 {
            text post.title bold
            text `por ${post.author.name}` muted small
          }
        }
      }
    }
  }
}

