page Home "/" {
  state currentPage = 1
  computed itemsPerPage = 10
  computed totalItems = 23
  computed totalPages = Math.ceil(totalItems / itemsPerPage)
  computed startIndex = (currentPage - 1) * itemsPerPage
  computed endIndex = Math.min(startIndex + itemsPerPage, totalItems)
  computed items = Array.from({ length: endIndex - startIndex }, (_, i) => ({
    id: startIndex + i + 1,
    name: `Ítem ${startIndex + i + 1}`
