interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  r: number;
}

export function make(): Ball {
  return {
    x: Math.random() * 380 + 10,
    y: Math.random() * 280 + 10,
    vx: (Math.random() - 0.5) * 4,
    vy: (Math.random() - 0.5) * 4,
    r: 10,
  };
}

export function step(balls: Ball[]): void {
  // Gravity
  for (const b of balls) {
    b.vy += 0.2;
  }

  // Update positions
  for (const b of balls) {
    b.x += b.vx;
    b.y += b.vy;
  }

  // Bounce off walls
  for (const b of balls) {
    if (b.x - b.r < 0) {
      b.x = b.r;
      b.vx = -b.vx;
    }
    if (b.x + b.r > 400) {
      b.x = 400 - b.r;
      b.vx = -b.vx;
    }
    if (b.y - b.r < 0) {
      b.y = b.r;
      b.vy = -b.vy;
    }
    if (b.y + b.r > 300) {
      b.y = 300 - b.r;
      b.vy = -b.vy;
    }
  }

  // Elastic collision between balls
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const b1 = balls[i];
      const b2 = balls[j];
      const dx = b2.x - b1.x;
      const dy = b2.y - b1.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < b1.r + b2.r) {
        // Swap velocities (simplified elastic collision)
        const temp_vx = b1.vx;
        const temp_vy = b1.vy;
        b1.vx = b2.vx;
        b1.vy = b2.vy;
        b2.vx = temp_vx;
        b2.vy = temp_vy;

        // Separate balls to avoid overlap
        const overlap = b1.r + b2.r - dist;
        const nx = dx / dist;
        const ny = dy / dist;
        b1.x -= (overlap / 2) * nx;
        b1.y -= (overlap / 2) * ny;
        b2.x += (overlap / 2) * nx;
        b2.y += (overlap / 2) * ny;
      }
    }
  }
}

export function draw(canvas: HTMLCanvasElement | null, balls: Ball[]): void {
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;

  ctx.clearRect(0, 0, 400, 300);
  ctx.fillStyle = "#3b82f6";

  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fill();
  }
}

