export interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  r: number;
}

export function make(): Ball {
  return {
    x: Math.random() * 380 + 10,
    y: Math.random() * 280 + 10,
    vx: (Math.random() - 0.5) * 4,
    vy: (Math.random() - 0.5) * 4,
    r: 10,
  };
}

export function step(balls: Ball[]): void {
  const gravity = 0.2;
  const width = 400;
  const height = 300;

  for (const ball of balls) {
    ball.vy += gravity;
    ball.x += ball.vx;
    ball.y += ball.vy;

    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    }
    if (ball.x + ball.r > width) {
      ball.x = width - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }
    if (ball.y + ball.r > height) {
      ball.y = height - ball.r;
      ball.vy = -Math.abs(ball.vy);
    }
  }

  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const b1 = balls[i];
      const b2 = balls[j];
      const dx = b2.x - b1.x;
      const dy = b2.y - b1.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < b1.r + b2.r) {
        const temp_vx = b1.vx;
        const temp_vy = b1.vy;
        b1.vx = b2.vx;
        b1.vy = b2.vy;
        b2.vx = temp_vx;
        b2.vy = temp_vy;

        const overlap = b1.r + b2.r - dist;
        const ratio = overlap / 2;
        const nx = dx / dist;
        const ny = dy / dist;
        b1.x -= nx * ratio;
        b1.y -= ny * ratio;
        b2.x += nx * ratio;
        b2.y += ny * ratio;
      }
    }
  }
}

export function draw(canvas: HTMLCanvasElement, balls: Ball[]): void {
  const ctx = canvas.getContext("2d");
  if (!ctx) return;

  ctx.fillStyle = "#f0f0f0";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.strokeStyle = "#333";
  ctx.lineWidth = 1;
  ctx.strokeRect(0, 0, canvas.width, canvas.height);

  for (const ball of balls) {
    ctx.fillStyle = "#3b82f6";
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
    ctx.fill();
  }
}

