model RegistrationData {
  name: String
  plan: String
  newsletter: Bool = false
}

page Registration "/" {
  state step = 1
  state data: RegistrationData = { name: "", plan: "Gratis", newsletter: false }
  state nameError = ""
  state confirmed = false

  fn validateName() {
    if data.name.trim() == "" {
      nameError = "Nombre requerido"
      return false
    }
    nameError = ""
    return true
  }

  fn nextStep() {
    if step == 1 {
      if validateName() {
        step = 2
      }
    } else if step == 2 {
      step = 3
    }
  }

  fn prevStep() {
    if step > 1 {
      step = step - 1
    }
  }

  fn confirm() {
    confirmed = true
  }

  column gap=4 pad=4 {
    if confirmed {
      title "¡Listo, ${data.name}!"
    } else {
      column gap=2 {
        title "Paso ${step} de 3"

        if step == 1 {
          column gap=3 {
            input data.name placeholder="Nombre" -> data.name
            if nameError != "" {
              text nameError danger
            }
            button "Siguiente" primary -> nextStep()
          }
        }

        if step == 2 {
          column gap=3 {
            select data.plan options=["Gratis", "Pro"] -> data.plan
            checkbox data.newsletter label="Recibir novedades" -> data.newsletter
            row gap=2 {
              button "Atrás" -> prevStep()
              button "Siguiente" primary -> nextStep()
            }
          }
        }

        if step == 3 {
          column gap=3 {
            text "${data.name} eligió ${data.plan}"
            if data.newsletter {
              text "Con novedades"
            }
            row gap=2 {
              button "Atrás" -> prevStep()
              button "Confirmar" primary -> confirm()
            }
          }
        }
      }
    }
  }
}

