model Task {
  id: ID
  title: String min=1
  done: Bool = false
}

api tasks: Task

page Home "/" {
  state draft = ""
  state filter = "Todas"
  state editingId: ID? = null
  state editingTitle = ""
  data tasks = api.tasks.list()

  computed filtered = 
    filter == "Pendientes" ? tasks.filter(t => !t.done) :
    filter == "Hechas" ? tasks.filter(t => t.done) :
    tasks

  fn add() {
    if draft.trim() == "" { return }
    await api.tasks.create({ title: draft.trim(), done: false })
    draft = ""
  }

  fn markDone(id: ID) {
    await api.tasks.update(id, { done: true })
  }

  fn startRename(id: ID, title: String) {
    editingId = id
    editingTitle = title
  }

  fn saveRename(id: ID) {
    if editingTitle.trim() == "" { return }
    await api.tasks.update(id, { title: editingTitle.trim() })
    editingId = null
  }

  fn remove(id: ID) {
    await api.tasks.remove(id)
  }

  column gap=4 pad=4 {
    title "Gestor de Tareas"

    row gap=2 {
      input draft placeholder="Tarea" -> add()
      button "Agregar" primary -> add()
    }

    select filter options=["Todas", "Pendientes", "Hechas"]

    if filtered.length == 0 {
      text "No hay tareas" muted
    } else {
      column gap=2 {
        for t in filtered key t.id {
          row gap=2 align=center pad=2 {
            if editingId == t.id {
              input editingTitle placeholder="Nuevo título"
              button "Guardar" primary -> saveRename(t.id)
              button "Cancelar" -> { editingId = null }
            } else {
              text `${t.title}${t.done ? " (hecha)" : ""}` muted=t.done
              if !t.done {
                button "Hecha" small -> markDone(t.id)
              }
              button "Renombrar" small -> startRename(t.id, t.title)
              button "Eliminar" small danger -> remove(t.id)
            }
          }
        }
      }
    }
  }
}

