  id: ID
  option: String
  createdAt: Date = now()
}

api votes: Vote

server fn getStats() {
  let all = db.votes.list({ limit: 1000 })
  let dogs = all.filter(v => v.option == "dogs").length
  let cats = all.filter(v => v.option == "cats").length
  let total = dogs + cats

  return {
    dogs: dogs,
    cats: cats,
    dogsPercent: total == 0 ? 0 : Math.round((dogs / total) * 100),
    catsPercent: total == 0 ? 0 : Math.round((cats / total) * 100),
    total: total
  }
}

server fn resetVotes() {
  let all = db.votes.list({ limit: 10000 })
  for (let v of all) {
    db.votes.remove(v.id)
  }
}

page Poll "/" {
  state stats = { dogs: 0, cats: 0, dogsPercent: 0, catsPercent: 0, total: 0 }
  state loading = false

  fn refreshStats() {
    loading = true
    try {
      stats = await server.getStats()
    } catch (e) {
      console.error(e)
    }
    loading = false
  }

  fn vote(option: String) {
    loading = true
    try {
      await api.votes.create({ option: option })
      await refreshStats()
    } catch (e) {
      console.error(e)
    }
    loading = false
  }

  fn reset() {
    loading = true
    try {
      await server.resetVotes()
      await refreshStats()
    } catch (e) {
      console.error(e)
    }
    loading = false
  }

  mount {
    refreshStats()
  }

  column gap=4 pad=4 {
    title "¿Perros o Gatos?"

    card {
      column gap=3 {
        row gap=2 align=center {
          text "🐕 Perros"
          text `${stats.dogsPercent}% (${stats.dogs} votos)` small
        }
        button "Votar Perros" primary disabled=loading -> vote("dogs")
      }
    }

    card {
      column gap=3 {
        row gap=2 align=center {
          text "🐈 Gatos"
          text `${stats.catsPercent}% (${stats.cats} votos)` small
