    draftNote = ""
    error = ""
    notes = []
  }

  fn addNote() {
    if draftNote.trim() == "" { return }
    try {
      await api.notes.create({ title: draftNote.trim(), owner: me?.id ?? "" })
      draftNote = ""
      notes = await api.notes.list()
    } catch (e) {
      error = e.message
    }
  }

  fn removeNote(id: ID) {
    try {
      await api.notes.remove(id)
      notes = await api.notes.list()
    } catch (e) {
      error = e.message
    }
  }

  column gap=4 pad=4 {
    if !me {
      card gap=3 pad=3 {
        title "Mis Notas"
        form gap=2 -> login() {
          input email placeholder="Email" type=email required
          input password placeholder="Contraseña" type=password required
          if error != "" {
            text error danger
          }
          button "Entrar" primary
          button "Crear cuenta" -> signup()
        }
      }
    } else {
      column gap=3 {
        row align=center justify="between" {
          text `Hola, ${me.email}` bold
          button "Salir" -> logout()
        }
        form gap=2 -> addNote() {
          row gap=2 {
            input draftNote placeholder="Nota" required
            button "Agregar" primary
          }
        }
        if error != "" {
          text error danger
        }
        if notes.length == 0 {
          text "Sin notas" muted
        } else {
          column gap=2 {
            for note in notes key note.id {
              row align=center justify="between" {
                text note.title
                button "×" small danger -> removeNote(note.id)
              }
            }
          }
        }
      }
    }
  }
}

